def authorize_phase_b(control:dict)->dict:
    """Create technical mirrors of externally supplied Phase-B bytes and SHA values."""
    root=control["root"];release=json.loads(control["release"].read_text());handoff_path=control["roots"]["side_records"]/driver.PHASE_A_HANDOFF_PATH
    handoff=json.loads(handoff_path.read_text());handoff_sha=sha_file(handoff_path)
    common={"repair_id":driver.REPAIR,"task_id":driver.TASK_ID,"batch_id":"B1","run_id":release["run_id"],"mode":driver.MODE,"claim_ceiling":driver.CLAIM,"verification_subject_count":27,"phase_a_commands_exact":list(driver.PHASE_A_COMMANDS),"phase_a_permissions":driver.PHASE_A_PERMISSIONS,"phase_a_release_path":"control/RELEASE.json","phase_a_release_sha256":sha_file(control["release"]),"phase_a_attestation_path":"control/GUARDIAN_ATTESTATION.json","phase_a_attestation_sha256":sha_file(control["attestation"]),"phase_a_handoff_path":release["roots"]["side_records"]+"/"+driver.PHASE_A_HANDOFF_PATH,"phase_a_handoff_sha256":handoff_sha,"phase_a_handoff_digest":handoff["handoff_digest"],"verification_subject_seal_path":handoff["verification_subject_seal_path"],"verification_subject_seal_sha256":handoff["verification_subject_seal_sha256"],"verification_subject_digest":handoff["verification_subject_digest"],"source_manifest_sha256":release["source_manifest_sha256"],"schema_manifest_sha256":release["schema_manifest_sha256"],"command_manifest_sha256":release["command_manifest_sha256"],"projection_contract_sha256":release["projection_contract_sha256"],"dependency_matrix_sha256":release["dependency_matrix_sha256"],"dependency_structure_sha256":release["dependency_structure_sha256"],"roots":release["roots"],"phase_b_commands_exact":list(driver.PHASE_B_COMMANDS),"phase_b_permissions":driver.PHASE_B_PERMISSIONS,"final_test_read":False}
    auth={"schema_version":"gen_enc_fast_two_phase_guardian_phase_b_authorization_v1","record_kind":"TECHNICAL_MIRROR_GUARDIAN_PHASE_B_AUTHORIZATION","identity_class":"TECHNICAL_ONLY_NEVER_FORMAL","authoritative":False,"authorization_id":sha_value({"handoff":handoff_sha,"phase":"B-auth"}),**common}
    common.update({"authority_allowlist_path":release["authority_allowlist_path"],"authority_allowlist_sha256":release["authority_allowlist_sha256"],"source_manifest_path":release["source_manifest_path"],"schema_manifest_path":release["schema_manifest_path"],"command_manifest_path":release["command_manifest_path"],"projection_contract_path":release["projection_contract_path"],"dependency_matrix_path":release["dependency_matrix_path"],"phase_a_task_id":driver.TASK_ID,"phase_b_task_id":driver.TASK_ID,"guardian_two_phase_contract_path":driver.GUARDIAN_TWO_PHASE_CONTRACT_PATH,"guardian_two_phase_contract_sha256":driver.GUARDIAN_TWO_PHASE_CONTRACT_SHA256,"guardian_two_phase_review_path":driver.GUARDIAN_TWO_PHASE_REVIEW_PATH,"guardian_two_phase_review_sha256":driver.GUARDIAN_TWO_PHASE_REVIEW_SHA256,"phase_b_authorization_path":driver.PHASE_B_AUTH_PATH,"phase_b_attestation_path":driver.PHASE_B_ATTESTATION_PATH,"phase_b_dispatch_path":driver.PHASE_B_DISPATCH_PATH,"independent_report_sha256":handoff["independent_report_sha256"],"verifier_terminal_sha256":handoff["verifier_terminal_sha256"],"artifact_graph_digest":handoff["artifact_graph_digest"],"issued_at":datetime.now(timezone.utc).isoformat(),"expires_at":(datetime.now(timezone.utc)+timedelta(hours=2)).isoformat(),"one_use":True,"revoked":False});auth.update(common)
    auth_path=root/driver.PHASE_B_AUTH_PATH;write(auth_path,auth);auth_sha=sha_file(auth_path)
    att={"schema_version":"gen_enc_fast_two_phase_guardian_phase_b_attestation_v1","record_kind":"TECHNICAL_MIRROR_GUARDIAN_PHASE_B_ONE_WAY_ATTESTATION","identity_class":"TECHNICAL_ONLY_NEVER_FORMAL","authoritative":False,"authorization_id":auth["authorization_id"],"authorization_sha256":auth_sha,"one_way":True,**common}
    att_path=root/driver.PHASE_B_ATTESTATION_PATH;write(att_path,att);att_sha=sha_file(att_path)
    dispatch_id=sha_value({"handoff":handoff_sha,"phase":"B-dispatch"})
    dispatch={"schema_version":"gen_enc_fast_b1_repair_07_phase_b_dispatch_v1","record_kind":"TECHNICAL_PHASE_DISPATCH","state":"PHASE_B_ISSUED","phase":"B","dispatch_id":dispatch_id,"phase_a_dispatch_id":release["phase_a_dispatch_id"],"authorization_id":auth["authorization_id"],"authorization_sha256":auth_sha,"phase_b_attestation_sha256":att_sha,**common,"one_use":True,"revoked":False}
    dispatch_path=root/driver.PHASE_B_DISPATCH_PATH;write(dispatch_path,dispatch);dispatch_sha=sha_file(dispatch_path)
    return {"authorization":auth_path,"authorization_sha256":auth_sha,"phase_b_attestation":att_path,"phase_b_attestation_sha256":att_sha,"dispatch":dispatch_path,"dispatch_sha256":dispatch_sha,"dispatch_id":dispatch_id}
